/* From Uiverse.io by Praashoo7 - Tags: animation, loading, loader */
.__UIV_SCOPE__ .loading {
  transform: translate(0%, -50%);
}

.__UIV_SCOPE__ .l {
  color: black;
  opacity: 0;
  animation: op 2s ease-in-out infinite;
  animation-delay: 0.2s;
}

.__UIV_SCOPE__ .o {
  color: black;
  opacity: 0;
  animation: op 2s ease-in-out infinite;
  animation-delay: 0.4s;
}

.__UIV_SCOPE__ .a {
  color: black;
  opacity: 0;
  animation: op 2s ease-in-out infinite;
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .d {
  color: black;
  opacity: 0;
  animation: op 2s ease-in-out infinite;
  animation-delay: 0.8s;
}

.__UIV_SCOPE__ .i {
  color: black;
  opacity: 0;
  animation: op 2s ease-in-out infinite;
  animation-delay: 1s;
}

.__UIV_SCOPE__ .n {
  color: black;
  opacity: 0;
  animation: op 2s ease-in-out infinite;
  animation-delay: 1.2s;
}

.__UIV_SCOPE__ .g {
  color: black;
  opacity: 0;
  animation: op 2s ease-in-out infinite;
  animation-delay: 1.4s;
}

.__UIV_SCOPE__ .d1 {
  color: black;
  opacity: 0;
  animation: op1 2s ease-in-out infinite;
  animation-delay: 1.6s;
}

.__UIV_SCOPE__ .d2 {
  color: black;
  opacity: 0;
  animation: op1 2s ease-in-out infinite;
  animation-delay: 2s;
}

.__UIV_SCOPE__ .load {
  position: relative;
  width: 1.2em;
  height: 1.2em;
  border-radius: 50%;
}

.__UIV_SCOPE__ .progress {
  top: 50%;
  left: -80%;
  position: absolute;
  margin-top: 2.2em;
  transform: translate(10%, -50%);
  content: '';
  width: 3.1em;
  height: 3.1em;
  background: transparent;
  border-radius: 50%;
  animation: load_37100 2s ease-in-out infinite;
  animation-delay: 1s;
}

@keyframes load_37100 {
  0% {
    background-color: #DB4437;
  }

  25% {
    background-color: #F4B400;
  }

  75% {
    background-color: #0F9D58;
  }

  100% {
    background-color: #4285F4;
  }
}

.__UIV_SCOPE__ .progress:nth-child(2) {
  left: 50%;
  animation-delay: 1.3s;
}

.__UIV_SCOPE__ .progress:nth-child(3) {
  left: 180%;
  animation-delay: 1.7s;
}

.__UIV_SCOPE__ .progress:nth-child(4) {
  left: 300%;
  animation-delay: 2s;
}

@keyframes op {
  0% {
    color: black;
    opacity: 1;
  }

  50% {
    color: green;
    opacity: 1;
  }

  100% {
    color: black;
    opacity: 1;
  }
}

@keyframes op1 {
  0% {
    color: black;
    opacity: 1;
  }

  50% {
    color: green;
    opacity: 0;
  }

  100% {
    color: black;
    opacity: 1;
  }
}
